u32 kvm_lapic_get_current_count(struct kvm_lapic *apic)
{
    u64 period;
    u64 remaining;
    u32 count;

    if (!apic || !apic->base.shregs.timer.initial_count || !apic->base.shregs.timer.divide_count)
        return 0;

    period = apic->base.shregs.timer.initial_count *
             apic->base.shregs.timer.divide_count;

    remaining = apic->base.shregs.timer.initial_count -
                apic->base.shregs.timer.current_count;

    if (remaining > period)
        remaining = period;

    count = (u32)((remaining % period) / apic->base.shregs.timer.divide_count);

    return count;
}

u32 kvm_apic_get_current_count(struct kvm_lapic *apic)
{
    u64 initial_count, period, remaining, bus_cycle;
    u32 count;

    if (!apic)
        return 0;

    initial_count = apic->regs->tmr_initial_count;
    if (initial_count == 0)
        return 0;

    period = apic->lapic_timer_period;
    if (period == 0)
        return 0;

    remaining = (u64)kvm_apic_get_tscdeadline(apic) - rdtsc();
    if (remaining < 0)
        remaining = 0;

    bus_cycle = APIC_BUS_CYCLE_NS << apic->divide_count;
    count = (u32)((remaining % period) / bus_cycle);

    return count;
}

u32 kvm_apic_get_current_count(struct kvm_lapic *apic)
{
    u64 counter;
    u64 remaining;
    u32 count;

    if (!apic)
        return 0;

    if (!apic->timer.initial_count || !apic->timer.period)
        return 0;

    counter = apic_read_counter(apic);
    if (counter > apic->timer.initial_count)
        return 0;

    remaining = apic->timer.initial_count - counter;

    count = (u32)((remaining % apic->timer.period) /
                  (apic->divide_count ? apic->divide_count : 1));

    return count;
}

u32 kvm_apic_get_current_count(struct kvm_lapic *apic)
{
    u64 period, remaining, bus_clock;

    if (!apic || !apic->timer.initial_count || !apic->timer.period)
        return 0;

    period = (u64)apic->timer.initial_count * NSEC_PER_SEC;
    period /= apic->timer.divide_count;

    remaining = period - (kvm_clock_read() % period);
    if (remaining < 0)
        remaining = 0;

    bus_clock = period / apic->timer.divide_count;
    return (u32)(remaining / bus_clock);
}

u32 kvm_lapic_get_current_count(struct kvm_lapic *apic)
{
    u64 period, delta, count;

    if (!apic)
        return 0;

    if (apic->base.shregs.divide_configuration & APIC_DIV_BUSY)
        return 0;

    if (!apic->base.shregs.initial_count)
        return 0;

    period = apic->base.shregs.initial_count * 1000000000ULL;
    period = period / apic->base.shregs.divide_count;

    delta = ktime_get_real_ns() - apic->base.shregs.tsc_deadline;
    if (delta >= period)
        return 0;

    count = (period - delta) % period;
    count = count * apic->base.shregs.divide_count / (1 << apic->base.shregs.divide_configuration);

    return count;
}
